#[cfg(test)]
mod tests {
    use rigorix_engine::effect_commitment::application::{
        ProviderReceiptConfig, ProviderReceiptReader,
    };
    use rigorix_engine::effect_commitment::infrastructure::HttpProviderReceiptReader;

    #[test]
    fn test_providerreceiptreader_is_defined() {
        // The L3 boundary is a port: adapters produce evidence, never a boolean
        // guess, so the engine can be programmed against it without a provider
        // dependency.
        fn assert_object_safe(_: Option<Box<dyn ProviderReceiptReader>>) {}
        assert_object_safe(None);

        fn assert_send_sync<T: Send + Sync + ?Sized>() {}
        assert_send_sync::<dyn ProviderReceiptReader>();
    }

    #[test]
    fn test_providerreceiptreader_interacts_with_observedoutcome() {
        let cfg = ProviderReceiptConfig::new(
            "https://payments.example",
            "stripe",
            1_000,
            1_024,
            Some("super-secret".to_string()),
        );

        // The adapter implements the port and never leaks the credential.
        let reader = HttpProviderReceiptReader::new(cfg.clone());
        assert_eq!(reader.config().provider_id, "stripe");
        let _port: &dyn ProviderReceiptReader = &reader;

        let rendered = format!("{cfg:?}");
        assert!(!rendered.contains("super-secret"));
        assert!(rendered.contains("<redacted>"));
    }
}
